<?php
require_once __DIR__.'/includes/auth.php';require_roles(['ADMIN','ORGANIZADOR']);require_once __DIR__.'/includes/helpers.php';$pageTitle='Apertura de torneo';
try{$games=option_map('videojuegos');$platforms=option_map('plataformas');$venues=option_map('sedes');$formats=option_map('formatos');$cats=option_map('categorias');$sponsors=option_map('patrocinadores');$torneos=lookup_rows('torneos');
if($_SERVER['REQUEST_METHOD']==='POST'){
 $sql="BEGIN AV_JP_RM_BE_SP_ABRIR_TORNEO(:P_ID,:P_NOMBRE,:P_ID_VIDEOJUEGO,:P_ID_PLATAFORMA,:P_ID_SEDE,:P_ID_FORMATO,:P_ID_CATEGORIA,:P_ID_ORGANIZADOR,TO_DATE(:P_FECHA_INICIO,'YYYY-MM-DD'),TO_DATE(:P_FECHA_FIN,'YYYY-MM-DD'),:P_CUPO_MAXIMO,:P_COSTO_INSCRIPCION,:P_PREMIO_TOTAL,:P_ID_PATROCINADOR,:P_MONTO_APORTE); END;";
 $p=['P_ID'=>0,'P_NOMBRE'=>$_POST['nombre'],'P_ID_VIDEOJUEGO'=>$_POST['videojuego'],'P_ID_PLATAFORMA'=>$_POST['plataforma'],'P_ID_SEDE'=>$_POST['sede'],'P_ID_FORMATO'=>$_POST['formato'],'P_ID_CATEGORIA'=>$_POST['categoria'],'P_ID_ORGANIZADOR'=>current_user()['ID_USUARIO'],'P_FECHA_INICIO'=>$_POST['fecha_inicio'],'P_FECHA_FIN'=>$_POST['fecha_fin'],'P_CUPO_MAXIMO'=>$_POST['cupo'],'P_COSTO_INSCRIPCION'=>$_POST['costo'],'P_PREMIO_TOTAL'=>$_POST['premio'],'P_ID_PATROCINADOR'=>$_POST['patrocinador']?:null,'P_MONTO_APORTE'=>$_POST['aporte']?:0];
 $out=oracle_run($sql,$p,['P_ID']);flash('success','Torneo creado con ID '.$out['P_ID'].'.');header('Location: gestor_torneos.php');exit;}
}catch(Throwable $e){$error=$e->getMessage();}
include __DIR__.'/includes/header.php';function opts($a){foreach($a as $v=>$l)echo '<option value="'.h($v).'">'.h($l).'</option>';}?>
<main class="content"><div class="page-head"><div><h1>🏆 Apertura de torneos</h1><p>Gestor 1: cruza juego, plataforma, sede, formato, categoría y patrocinador.</p></div></div><?php if(!empty($error)):?><div class="callout" style="border-color:#ff667d"><?=h($error)?></div><?php endif;?><div class="split"><section class="panel"><h2 class="section-title">Nuevo torneo</h2><form method="post"><div class="grid grid-2"><div class="field"><label>Nombre *</label><input name="nombre" required></div><div class="field"><label>Videojuego *</label><select name="videojuego" required><?php opts($games??[])?></select></div><div class="field"><label>Plataforma *</label><select name="plataforma" required><?php opts($platforms??[])?></select></div><div class="field"><label>Sede *</label><select name="sede" required><?php opts($venues??[])?></select></div><div class="field"><label>Formato *</label><select name="formato" required><?php opts($formats??[])?></select></div><div class="field"><label>Categoría *</label><select name="categoria" required><?php opts($cats??[])?></select></div><div class="field"><label>Fecha inicio *</label><input type="date" name="fecha_inicio" required></div><div class="field"><label>Fecha fin *</label><input type="date" name="fecha_fin" required></div><div class="field"><label>Cupo máximo *</label><input type="number" min="2" name="cupo" required></div><div class="field"><label>Costo inscripción</label><input type="number" min="0" name="costo" value="0"></div><div class="field"><label>Premio total</label><input type="number" min="0" name="premio" value="0"></div><div class="field"><label>Patrocinador (opcional)</label><select name="patrocinador"><option value="">Sin patrocinador</option><?php opts($sponsors??[])?></select></div><div class="field"><label>Aporte patrocinador</label><input type="number" min="0" name="aporte" value="0"></div></div><div class="form-actions"><button class="btn">Crear torneo</button></div></form></section><section class="panel"><h2 class="section-title">Torneos registrados</h2><div class="table-wrap"><table><thead><tr><th>ID</th><th>Nombre</th><th>Juego</th><th>Sede</th><th>Formato</th><th>Cupos</th><th>Estado</th></tr></thead><tbody><?php foreach($torneos??[] as $t):?><tr><td><?=h($t['ID_TORNEO'])?></td><td><?=h($t['NOMBRE'])?></td><td><?=h($t['VIDEOJUEGO'])?></td><td><?=h($t['SEDE'])?></td><td><?=h($t['FORMATO'])?></td><td><?=h($t['CUPO_MAXIMO'])?></td><td><span class="badge <?=h($t['ESTADO'])?>"><?=h($t['ESTADO'])?></span></td></tr><?php endforeach;?></tbody></table></div></section></div></main><?php include __DIR__.'/includes/footer.php';?>
